import { cn } from "@/lib/utils";
import {
  parseNumericValue,
  type NumericValue,
} from "@/lib/onchain/format";
import { TokenLogo, type TokenLogoProps } from "./token-logo";
import { TokenPrice, type TokenPriceProps } from "./token-price";
import type { ReactNode } from "react";

type BalanceValue = NumericValue;

export interface TokenBalanceProps {
  /** Token amount */
  amount: BalanceValue;
  /** Token symbol, shown after the amount */
  symbol?: string | null | undefined;
  /** Token name, used for logo alt text */
  name?: string | null | undefined;
  /** Token image URL */
  src?: string | null | undefined;
  /** Token contract address, used for icon inference and as a fallback label */
  address?: string | null | undefined;
  /** EVM chain id, used with address to infer a token icon */
  chainId?: number | null | undefined;
  /** Whether the asset is the chain's native currency */
  isNative?: boolean | undefined;
  /** Fiat value for the token balance */
  fiatValue?: TokenPriceProps["value"] | undefined;
  /** Fiat value percentage change */
  change?: TokenPriceProps["change"] | undefined;
  /** Show the token logo. Default: true */
  showLogo?: boolean | undefined;
  /** Show fiat value when provided. Default: true */
  showFiatValue?: boolean | undefined;
  /** Locale passed to Intl.NumberFormat */
  locale?: string | undefined;
  /** Maximum fraction digits for the token amount. Default: 4 */
  maximumFractionDigits?: number | undefined;
  /** Minimum fraction digits for the token amount */
  minimumFractionDigits?: number | undefined;
  /** Value shown when amount is null, undefined, empty, or invalid. Default: -- */
  fallback?: ReactNode | undefined;
  /** Props passed to TokenLogo */
  logoProps?: Partial<TokenLogoProps> | undefined;
  /** Props passed to TokenPrice */
  priceProps?: Partial<TokenPriceProps> | undefined;
  /** Applied to the root wrapper */
  className?: string | undefined;
  /** Applied to the amount line */
  amountClassName?: string | undefined;
  /** Applied to the fiat value line */
  fiatClassName?: string | undefined;
}

function formatAmount({
  locale,
  maximumFractionDigits,
  minimumFractionDigits,
  value,
}: {
  locale?: string | undefined;
  maximumFractionDigits: number;
  minimumFractionDigits?: number | undefined;
  value: number;
}) {
  return new Intl.NumberFormat(locale, {
    // Intl.NumberFormat throws a RangeError when min > max
    maximumFractionDigits: Math.max(
      maximumFractionDigits,
      minimumFractionDigits ?? 0
    ),
    minimumFractionDigits,
  }).format(value);
}

export function TokenBalance({
  amount,
  symbol,
  name,
  src,
  address,
  chainId,
  isNative = false,
  fiatValue,
  change,
  showLogo = true,
  showFiatValue = true,
  locale,
  maximumFractionDigits = 4,
  minimumFractionDigits,
  fallback = "--",
  logoProps,
  priceProps,
  className,
  amountClassName,
  fiatClassName,
}: TokenBalanceProps) {
  const parsedAmount = parseNumericValue(amount);
  const hasFiatValue =
    showFiatValue && fiatValue !== null && fiatValue !== undefined && fiatValue !== "";

  return (
    <div className={cn("inline-flex items-center gap-3", className)}>
      {showLogo && (
        <TokenLogo
          address={address}
          chainId={chainId}
          isNative={isNative}
          name={name}
          src={src}
          symbol={symbol}
          {...logoProps}
        />
      )}

      <div className="grid min-w-0 gap-0.5">
        <div
          className={cn(
            "font-mono text-sm font-medium tabular-nums",
            amountClassName
          )}
        >
          {parsedAmount === null
            ? fallback
            : formatAmount({
                locale,
                maximumFractionDigits,
                minimumFractionDigits,
                value: parsedAmount,
              })}
          {symbol && <span className="ml-1 text-muted-foreground">{symbol}</span>}
        </div>

        {hasFiatValue && (
          <TokenPrice
            value={fiatValue}
            change={change}
            className={cn("text-xs text-muted-foreground", fiatClassName)}
            priceClassName="font-mono"
            {...priceProps}
          />
        )}
      </div>
    </div>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { getTokenIcon } from "@/lib/onchain/crypto-icons";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

const sizeClasses = {
  xs: "size-5 text-[9px]",
  sm: "size-6 text-[10px]",
  md: "size-8 text-xs",
  lg: "size-10 text-sm",
  xl: "size-12 text-base",
} as const;

// Pixel sizes for layouts that size marks in px rather than steps. The font
// tracks the named sizes (~3/8 of the diameter) with a floor for legibility.
// Kept as numbers for a literal style object: shadcn/lint's no-inline-styles
// cannot check a computed one.
function getPixelFontSize(size: number) {
  return Math.max(8, Math.round(size * 0.375));
}

export interface TokenLogoProps {
  /** Token image URL. Always wins over inferred icons */
  src?: string | null | undefined;
  /** Token symbol, used for alt text and fallback initials */
  symbol?: string | null | undefined;
  /** Token name, used for alt text */
  name?: string | null | undefined;
  /** Token contract address, used for icon inference and as a fallback label */
  address?: string | null | undefined;
  /** EVM chain id, used with address to infer an icon via the crypto-icons adapter */
  chainId?: number | null | undefined;
  /** Use the native-currency icon rather than the wrapped token at `address` */
  isNative?: boolean | undefined;
  /** Named size, or a diameter in pixels such as 28. Default: md */
  size?: keyof typeof sizeClasses | number | undefined;
  /** Custom fallback content when the image is missing or fails */
  fallback?: ReactNode | undefined;
  /** Show an animated tooltip. Default: false */
  showTooltip?: boolean | undefined;
  /** Tooltip content. Defaults to name, symbol, then address. */
  tooltipContent?: ReactNode | undefined;
  /**
   * `tile` draws the image on a bordered muted circle. `bare` draws it on
   * nothing, for logos that bring their own padding on a transparent canvas,
   * where a tile reads as a ring around every mark. Default: tile
   */
  variant?: "tile" | "bare" | undefined;
  /** Load the image eagerly at high priority, for logos above the fold */
  priority?: boolean | undefined;
  /** Applied to the root wrapper */
  className?: string | undefined;
  /** Applied to the image */
  imageClassName?: string | undefined;
  /** Applied to the fallback */
  fallbackClassName?: string | undefined;
}

function getFallbackText({
  address,
  name,
  symbol,
}: Pick<TokenLogoProps, "address" | "name" | "symbol">) {
  if (symbol) return symbol.slice(0, 4).toUpperCase();
  if (name) return name.slice(0, 2).toUpperCase();
  if (address) return address.slice(2, 4).toUpperCase();
  return "?";
}

export function TokenLogo({
  src,
  symbol,
  name,
  address,
  chainId,
  isNative = false,
  size = "md",
  fallback,
  showTooltip = false,
  tooltipContent,
  variant = "tile",
  priority = false,
  className,
  imageClassName,
  fallbackClassName,
}: TokenLogoProps) {
  const [failedSrc, setFailedSrc] = useState<string | null>(null);

  // Explicit src wins; otherwise ask the crypto-icons adapter.
  const inferredIcon = useMemo(
    () =>
      src ? null : getTokenIcon({ chainId, address, isNative, symbol }),
    [address, chainId, isNative, src, symbol]
  );
  const resolvedSrc =
    src ?? (typeof inferredIcon === "string" ? inferredIcon : null);
  const inferredNode =
    inferredIcon != null && typeof inferredIcon !== "string"
      ? inferredIcon
      : null;
  const shouldShowImage = Boolean(resolvedSrc) && failedSrc !== resolvedSrc;

  const alt = useMemo(() => {
    if (name && symbol) return `${name} (${symbol})`;
    return name ?? symbol ?? address ?? "Token";
  }, [address, name, symbol]);

  const tooltip = tooltipContent ?? name ?? symbol ?? address;

  // The fallback keeps its tile in every variant, so a missing logo is still
  // a visible shape.
  const bare = variant === "bare" && (shouldShowImage || inferredNode != null);
  const px = typeof size === "number" ? size : undefined;

  const logo = (
    <span
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full font-medium text-muted-foreground",
        bare ? null : "border bg-muted",
        px === undefined ? sizeClasses[size as keyof typeof sizeClasses] : null,
        className
      )}
      style={{
        width: px,
        height: px,
        fontSize: px === undefined ? undefined : getPixelFontSize(px),
      }}
    >
      {shouldShowImage ? (
        <img
          src={resolvedSrc ?? undefined}
          alt={alt}
          className={cn(
            "size-full",
            variant === "bare" ? "object-contain" : "object-cover",
            imageClassName
          )}
          loading={priority ? "eager" : "lazy"}
          fetchPriority={priority ? "high" : undefined}
          decoding="async"
          referrerPolicy="no-referrer"
          onError={() => setFailedSrc(resolvedSrc)}
        />
      ) : inferredNode ? (
        inferredNode
      ) : (
        <span className={cn("select-none", fallbackClassName)}>
          {fallback ?? getFallbackText({ address, name, symbol })}
        </span>
      )}
    </span>
  );

  if (!showTooltip || tooltip == null) return logo;

  return (
    <Tooltip>
      <TooltipTrigger render={logo} />
      <TooltipContent>{tooltip}</TooltipContent>
    </Tooltip>
  );
}

import { ArrowDownIcon, ArrowUpIcon, MinusIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  parseNumericValue,
  type NumericValue,
} from "@/lib/onchain/format";
import type { ReactNode } from "react";

type PriceValue = NumericValue;
type Trend = "down" | "neutral" | "up";

// `positive` and `negative` are theme tokens, like `destructive`. Define
// `--positive` and `--negative` in your CSS to retheme gains and losses; until
// you do, the registry's light and dark defaults (`--onchain-positive`,
// `--onchain-negative`) apply. The defaults use their own names so installing
// never overrides tokens you already have, in any mode.
const trendClasses = {
  down: "text-negative",
  neutral: "text-muted-foreground",
  up: "text-positive",
} as const;

export interface TokenPriceProps {
  /** Token price value */
  value: PriceValue;
  /** ISO 4217 currency code. Default: USD */
  currency?: string | undefined;
  /** Locale passed to Intl.NumberFormat */
  locale?: string | undefined;
  /** Use compact notation, e.g. $3.2K */
  compact?: boolean | undefined;
  /** Value shown when price is null, undefined, empty, or invalid. Default: -- */
  fallback?: ReactNode | undefined;
  /** Minimum fraction digits for the price */
  minimumFractionDigits?: number | undefined;
  /** Maximum fraction digits for the price */
  maximumFractionDigits?: number | undefined;
  /** 24h-style percentage change, e.g. -2.34 means -2.34% */
  change?: number | null | undefined;
  /** Override the derived change direction */
  trend?: Trend | undefined;
  /** Show trend icon before the change. Default: true */
  showChangeIcon?: boolean | undefined;
  /** Fraction digits for the change value. Default: 2 */
  changeFractionDigits?: number | undefined;
  /** Hide the plus sign for positive changes. Default: false */
  hidePositiveSign?: boolean | undefined;
  /**
   * Formats the price instead of Intl.NumberFormat, for apps with a house
   * number style. Receives the parsed number; currency, locale, compact and
   * the fraction digit props are then unused.
   */
  format?: ((value: number) => ReactNode) | undefined;
  /**
   * Formats the change instead of the default "+2.34%". Receives `change` as
   * passed, so an app that stores fractions (0.0234) can format them itself.
   */
  formatChange?: ((change: number) => ReactNode) | undefined;
  /** Applied to the root wrapper */
  className?: string | undefined;
  /** Applied to the formatted price */
  priceClassName?: string | undefined;
  /** Applied to the change badge */
  changeClassName?: string | undefined;
}

function getMaximumFractionDigits(value: number) {
  const abs = Math.abs(value);
  if (abs >= 1) return 2;
  if (abs >= 0.01) return 4;
  return 6;
}

function formatPrice({
  compact,
  currency,
  locale,
  maximumFractionDigits,
  minimumFractionDigits,
  value,
}: {
  compact: boolean;
  currency: string;
  locale?: string | undefined;
  maximumFractionDigits?: number | undefined;
  minimumFractionDigits?: number | undefined;
  value: number;
}) {
  const abs = Math.abs(value);
  const hasExplicitDigits =
    maximumFractionDigits !== undefined || minimumFractionDigits !== undefined;

  // Sub-cent prices round to $0.00 with fraction digits; keep the leading
  // significant figures instead, e.g. $0.00000041.
  if (!hasExplicitDigits && abs > 0 && abs < 0.01) {
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      currencyDisplay: "narrowSymbol",
      notation: compact ? "compact" : "standard",
      maximumSignificantDigits: 2,
    }).format(value);
  }

  const resolvedMaximumFractionDigits =
    maximumFractionDigits ?? getMaximumFractionDigits(value);

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    currencyDisplay: "narrowSymbol",
    notation: compact ? "compact" : "standard",
    minimumFractionDigits,
    // Intl.NumberFormat throws a RangeError when min > max
    maximumFractionDigits: Math.max(
      resolvedMaximumFractionDigits,
      minimumFractionDigits ?? 0
    ),
  }).format(value);
}

function getTrend(change?: number | null): Trend {
  if (!change) return "neutral";
  return change > 0 ? "up" : "down";
}

function formatPercent(
  change: number,
  fractionDigits: number,
  hidePositiveSign: boolean
) {
  const sign = change > 0 && !hidePositiveSign ? "+" : "";
  return `${sign}${change.toFixed(fractionDigits)}%`;
}

function TrendIcon({ trend }: { trend: Trend }) {
  if (trend === "up") return <ArrowUpIcon className="size-3" />;
  if (trend === "down") return <ArrowDownIcon className="size-3" />;
  return <MinusIcon className="size-3" />;
}

export function TokenPrice({
  value,
  currency = "USD",
  locale,
  compact = false,
  fallback = "--",
  minimumFractionDigits,
  maximumFractionDigits,
  change,
  trend,
  showChangeIcon = true,
  changeFractionDigits = 2,
  hidePositiveSign = false,
  format,
  formatChange,
  className,
  priceClassName,
  changeClassName,
}: TokenPriceProps) {
  const parsedValue = parseNumericValue(value);
  const shouldShowChange = typeof change === "number" && Number.isFinite(change);
  const derivedTrend = trend ?? getTrend(change);

  return (
    <span className={cn("inline-flex items-center gap-2", className)}>
      <span className={cn("font-mono tabular-nums", priceClassName)}>
        {parsedValue === null
          ? fallback
          : format
            ? format(parsedValue)
            : formatPrice({
              compact,
              currency,
              locale,
              maximumFractionDigits,
              minimumFractionDigits,
              value: parsedValue,
            })}
      </span>

      {shouldShowChange && (
        <span
          className={cn(
            "inline-flex items-center gap-0.5 font-mono text-xs tabular-nums",
            trendClasses[derivedTrend],
            changeClassName
          )}
        >
          {showChangeIcon && <TrendIcon trend={derivedTrend} />}
          {formatChange
            ? formatChange(change)
            : formatPercent(change, changeFractionDigits, hidePositiveSign)}
        </span>
      )}
    </span>
  );
}

export function truncateAddress(address: string, chars = 4): string {
  if (!address) return "";

  return `${address.slice(0, chars + 2)}…${address.slice(-chars)}`;
}

export type NumericValue = number | string | null | undefined;

/** Parses numbers and numeric strings; anything else becomes null. */
export function parseNumericValue(value: NumericValue): number | null {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}
